window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[91]={"id":"091","numero":91,"titre":"Déficit neurologique récent","objectifs":[{"id":"91-1","rang":"A","rubrique":"Définition","titre":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","contenu":"<div class=\"notion-course\"><h4>Définir ce qui est perdu</h4><table><thead><tr><th>Notion</th><th>À retenir</th></tr></thead><tbody><tr><td>Déficit neurologique</td><td>Perte d’une fonction liée à une dysfonction d’une région du système nerveux. Elle peut être transitoire ou persistante.</td></tr><tr><td>Récent</td><td>Apparu depuis <strong><span class=\"nc-pink nc-bold\">moins d’un mois</span></strong>. Ce délai décrit l’ancienneté, pas le degré d’urgence.</td></tr><tr><td>Déficit focal</td><td>Atteinte localisée : force, sensibilité, vision, langage ou coordination. Exemple : hémiparésie ou aphasie.</td></tr><tr><td>Trouble cérébral diffus</td><td>Perte de connaissance, coma ou syndrome confusionnel : altération globale, qui demande une analyse différente.</td></tr></tbody></table><ul><li>Un déficit focal peut <strong>coexister</strong> avec un trouble de conscience. Rechercher les deux.</li><li>Un déficit disparu reste à explorer : un examen redevenu normal n’exclut pas un AIT.</li><li>« Persistant » ne signifie pas nécessairement irréversible. Toute installation brutale impose une évaluation urgente.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Définitions clarifiées ; distinction entre ancienneté, persistance et urgence.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_830203/fr/accident-vasculaire-cerebral-prise-en-charge-precoce-alerte-phase-prehospitaliere-phase-hospitaliere-initiale-indications-de-la-thrombolyse\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Prise en charge précoce de l’AVC — actualisation partielle 2025</a></li></ul></details>","frequence":0},{"id":"91-2","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","contenu":"<div class=\"notion-course\"><h4>Vérifier qu’il s’agit d’une perte de fonction neurologique</h4><table><thead><tr><th>Présentation</th><th>Éléments d’orientation</th><th>Conduite</th></tr></thead><tbody><tr><td>Impotence ostéo-articulaire</td><td>Douleur au premier plan, limitation des mouvements ; fracture, entorse, arthrite, rupture de coiffe.</td><td>Examen articulaire, recherche de traumatisme ; imagerie ciblée selon la suspicion.</td></tr><tr><td>Ischémie aiguë d’un membre</td><td>Membre douloureux, froid, pâle ; pouls diminués ou absents. Un déficit sensitivo-moteur peut traduire une ischémie grave.</td><td>Avis <span class=\"nc-orange_bg\">vasculaire</span> immédiat. La douleur ne permet pas à elle seule d’écarter une atteinte neurologique.</td></tr><tr><td>Cause ORL ou ophtalmologique</td><td>Distinguer dysphonie et aphasie, vertige et malaise ; préciser si le trouble visuel est monoculaire ou touche un hémichamp.</td><td>Examen adapté. Une baisse visuelle brutale peut aussi relever d’une urgence <span class=\"nc-orange_bg\">vasculaire</span> ou ophtalmologique.</td></tr></tbody></table><h4>Si la présentation semble inhabituelle</h4><p>Un trouble neurologique fonctionnel se recherche sur des signes cliniques positifs, détaillés dans l’objectif suivant. Une présentation atypique ne suffit pas à le diagnostiquer.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Différentiels réorganisés ; les urgences vasculaires et sensorielles ne sont pas banalisées.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-1-item-72-troubles-a-symptomatologie-somatique-et-apparentes-a-tous-les-ages\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 72 — trouble neurologique fonctionnel</a></li></ul></details>","frequence":1},{"id":"91-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les arguments en faveur d'un déficit récent d'origine somatomorphe","contenu":"<div class=\"notion-course\"><h4>Reconnaître un trouble neurologique fonctionnel</h4><p>Le terme <strong>trouble neurologique fonctionnel (TNF)</strong> est aujourd’hui préféré à « somatomorphe ». Les symptômes sont réels et involontaires.</p><ul><li><strong>Signes positifs :</strong> discordance reproductible entre mouvement volontaire et automatique, variabilité selon les manœuvres, distribution incompatible avec l’anatomie.</li><li><strong>Exemple — signe de Hoover :</strong> l’extension de hanche apparemment faible redevient efficace pendant la flexion résistée de la hanche opposée.</li><li>Le contexte anxieux, une imagerie normale ou des plaintes changeantes ne suffisent pas. Un TNF peut coexister avec une maladie neurologique.</li><li>Évaluer les urgences et les diagnostics plausibles ; expliquer les signes positifs et organiser un avis neurologique. Le TNF n’est pas une simulation.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Correction de l’ancienne formulation « diagnostic d’élimination » et de l’amalgame avec la simulation, selon le chapitre consacré aux TNF.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-1-item-72-troubles-a-symptomatologie-somatique-et-apparentes-a-tous-les-ages\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 72 — trouble neurologique fonctionnel</a></li></ul></details>","frequence":1},{"id":"91-4","rang":"A","rubrique":"Diagnostic positif","titre":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","contenu":"<div class=\"notion-course\"><h4>Localiser avant de multiplier les examens</h4><table><thead><tr><th>Localisation</th><th>Arguments cliniques</th><th>Examen orienté</th></tr></thead><tbody><tr><td>Encéphale / tronc cérébral</td><td>Hémicorps atteint, aphasie, HLH ou troubles gnosiques ; paires crâniennes associées à une atteinte des voies longues ; signes pyramidaux.</td><td>IRM cérébrale ou TDM selon urgence et disponibilité ; exploration artérielle si AVC suspecté.</td></tr><tr><td>Moelle</td><td>Déficit sous-lésionnel, niveau sensitif thoracique ou abdominal, signes pyramidaux sous la lésion ; possibles troubles vésicosphinctériens.</td><td><span class=\"nc-blue_bg\">IRM médullaire</span> en urgence si installation aiguë.</td></tr><tr><td>Racine / plexus / nerf</td><td>Topographie radiculaire ou tronculaire, ROT diminués ou abolis ; amyotrophie et fasciculations possibles.</td><td>ENMG ciblé ; IRM lombaire urgente si queue de cheval suspectée.</td></tr><tr><td>Jonction neuromusculaire / muscle</td><td>Atteinte motrice pure : pas de trouble sensitif ni vésicosphinctérien. <span class=\"nc-blue_bg\">Déficit à prédominance proximale</span> ; réflexes souvent conservés.</td><td>ENMG ; CK si atteinte musculaire. Voir l’objectif 91-9.</td></tr></tbody></table><h4>Pièges de localisation</h4><ul><li>Une atteinte <span class=\"nc-orange nc-bold\">centrale</span> aiguë peut être <strong>flasque avec ROT diminués</strong> : l’aréflexie isolée ne prouve pas une origine périphérique.</li><li>L’amyotrophie peut manquer au début d’une atteinte périphérique ; certains territoires radiculaires n’ont pas de ROT directement testable.</li><li>La queue de cheval est <strong>périphérique</strong> et peut donner des troubles sphinctériens. La moelle appartient au SNC.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Ajout des pièges des ROT et de la topographie médullaire ; distinction muscle / jonction précisée.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-6-item-92-deficit-moteur-etou-sensitif-des-membres\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 92 — sémiologie et examens ; figure 6.9</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-7-item-93-compression-medullaire-non-traumatique-et-syndrome-de-la-queue-de-cheval\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 93 — compression médullaire et queue de cheval</a></li></ul></details>","frequence":1},{"id":"91-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","contenu":"<div class=\"notion-course\"><h4>Raisonner sans retarder les soins</h4><ul><li><strong>Dès l’accueil :</strong> rechercher une défaillance vitale, mesurer la glycémie capillaire et noter l’heure de début ou la dernière heure connue sans déficit.</li><li><strong>Caractériser :</strong> déficit moteur, sensitif, sensoriel, cérébelleux ou <span class=\"nc-blue_bg\">cognitif</span> ; préciser la répartition et les signes associés.</li><li><strong>Localiser :</strong> cerveau, tronc cérébral, moelle, racine, plexus, nerf, jonction ou muscle.</li><li><strong>Expliquer :</strong> confronter vitesse d’installation, évolution et contexte, puis demander les examens ciblés.</li></ul><table><thead><tr><th>Installation / évolution</th><th>Hypothèses à discuter</th></tr></thead><tbody><tr><td>Brutal, d’<span class=\"nc-pink nc-bold\">emblée maximal</span></td><td><span class=\"nc-orange_bg\">Vasculaire</span> en priorité : AVC jusqu’à preuve du contraire.</td></tr><tr><td>Quelques dizaines de <span class=\"nc-pink nc-bold\">secondes</span></td><td>Une marche <span class=\"nc-orange_bg\">épileptique</span> est possible ; elle ne permet pas d’exclure un AVC.</td></tr><tr><td>Extension sur quelques dizaines de <span class=\"nc-pink nc-bold\">minutes</span></td><td>Une marche <span class=\"nc-orange_bg\">migraineuse</span> est possible ; présentation nouvelle ou atypique : évaluation urgente.</td></tr><tr><td>Heures / jours</td><td>Inflammatoire, infectieux, toxique ; aussi thrombose veineuse cérébrale ou thrombose artérielle progressive.</td></tr><tr><td>Quelques semaines ; aggravation en tache d’huile</td><td>Processus <span class=\"nc-orange nc-bold\">expansif</span> : tumeur, abcès, <span class=\"nc-orange_bg\">hématome sous-dural</span> ; causes infectieuses ou métaboliques.</td></tr><tr><td>Transitoire</td><td>Reconstituer précisément l’épisode avec le patient et les témoins : AIT, crise, aura, hypoglycémie…</td></tr></tbody></table><h4>Interrogatoire utile</h4><p>Préciser traitements et anticoagulants, facteurs de risque <span class=\"nc-orange_bg\">vasculaire</span>, cancer, immunodépression, infection récente, traumatisme et toxiques. L’âge oriente sans exclure : un sujet jeune peut avoir un AVC.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. La recherche de gravité accompagne le raisonnement dès le départ ; temporalité et contexte complétés.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_830203/fr/accident-vasculaire-cerebral-prise-en-charge-precoce-alerte-phase-prehospitaliere-phase-hospitaliere-initiale-indications-de-la-thrombolyse\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Prise en charge précoce de l’AVC — actualisation partielle 2025</a></li></ul></details>","frequence":3},{"id":"91-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","contenu":"<div class=\"notion-course\"><h4>Choisir l’imagerie selon la localisation et l’urgence</h4><table><thead><tr><th>Situation</th><th>Imagerie et priorité</th></tr></thead><tbody><tr><td>Déficit central brutal, aigu ou suspicion d’AVC</td><td>Imagerie cérébrale immédiate : IRM si accessible sans retard, sinon TDM selon la filière. Imagerie artérielle cervico-encéphalique pour rechercher une occlusion.</td></tr><tr><td>Déficit après traumatisme crânien</td><td><span class=\"nc-blue_bg\">TDM cérébrale</span> sans injection immédiate : hématome extradural, sous-dural aigu, contusion ; avis neurochirurgical selon les lésions.</td></tr><tr><td>Déficit focal fébrile</td><td>Imagerie cérébrale urgente avant une PL lorsqu’une atteinte infectieuse <span class=\"nc-orange nc-bold\">centrale</span> est suspectée. Le traitement urgent ne doit pas attendre un examen retardé.</td></tr><tr><td>Syndrome médullaire aigu</td><td><span class=\"nc-blue_bg\">IRM médullaire</span> urgente, étendue selon la localisation et la cause recherchée.</td></tr><tr><td>Syndrome de la queue de cheval</td><td>IRM lombosacrée urgente ; l’ENMG ne remplace pas l’imagerie à cette étape.</td></tr><tr><td>Déficit progressif sans signe de gravité</td><td>Exploration rapide, en pratique dans les 24 heures selon le CEN ; reclasser en urgence si aggravation ou signe de gravité.</td></tr></tbody></table><p><strong>Supramédullaire signifie encéphalique</strong> : cerveau ou tronc cérébral. Une atteinte médullaire haute relève d’une exploration de la moelle, pas d’une IRM cérébrale seule.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Correction de la confusion « supramédullaire = médullaire haute » ; délais et priorités précisés.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_830203/fr/accident-vasculaire-cerebral-prise-en-charge-precoce-alerte-phase-prehospitaliere-phase-hospitaliere-initiale-indications-de-la-thrombolyse\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Prise en charge précoce de l’AVC — actualisation partielle 2025</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-7-item-93-compression-medullaire-non-traumatique-et-syndrome-de-la-queue-de-cheval\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 93 — compression médullaire et queue de cheval</a></li><li><a href=\"https://recospilf.infectiologie.com/pathologie/neuromeningees/encephalites-infectieuses/\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · Encéphalites infectieuses — version du 16/06/2026</a></li></ul></details>","frequence":1},{"id":"91-7","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes des déficits neurologiques récents centraux","contenu":"<div class=\"notion-course\"><h4>Causes centrales : cerveau, tronc cérébral et moelle</h4><table><thead><tr><th>Siège / mécanisme</th><th>Principales causes</th></tr></thead><tbody><tr><td>Encéphale — <span class=\"nc-orange_bg\">vasculaire</span></td><td>Infarctus cérébral, hémorragie intraparenchymateuse, thrombose veineuse cérébrale ; hémorragie méningée selon le contexte.</td></tr><tr><td>Encéphale — traumatique / <span class=\"nc-orange nc-bold\">expansif</span></td><td>Hématome extradural, <span class=\"nc-orange_bg\">hématome sous-dural</span>, contusion ; tumeur gliale, métastase, lymphome. Un sous-dural peut aussi être spontané.</td></tr><tr><td>Encéphale — infectieux / inflammatoire</td><td><span class=\"nc-purple_bg\">Méningo-encéphalite</span>, encéphalite, abcès cérébral, empyème ; poussée de SEP, Behçet, sarcoïdose.</td></tr><tr><td>Encéphale — autres</td><td>Déficit critique ou postcritique, état de mal focal ; hypoglycémie ; <span class=\"nc-red_bg\">encéphalopathie de Gayet-Wernicke</span> dans un contexte carentiel.</td></tr><tr><td>Moelle — compression</td><td>Hernie discale, tumeur, métastase, spondylodiscite / épidurite, hématome épidural, traumatisme.</td></tr><tr><td>Moelle — non compressif</td><td>Infarctus médullaire, notamment dans une <span class=\"nc-red nc-bold\">dissection aortique</span> ; <span class=\"nc-orange_bg\">myélite</span> inflammatoire ou infectieuse ; myélopathie carentielle.</td></tr></tbody></table><ul><li>Un déficit soudain peut révéler une lésion préexistante à l’occasion d’une crise <span class=\"nc-orange_bg\">épileptique</span>.</li><li>Un syndrome médullaire aigu impose d’abord de rechercher une compression ; la PL vient après cette étape si elle est indiquée.</li><li>Gayet-Wernicke évoque surtout une association confusion, ataxie et troubles oculomoteurs ; ne pas attribuer automatiquement une hémiparésie brutale à une carence.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Causes critiques et métaboliques ajoutées ; urgences compressives mieux identifiées.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-7-item-93-compression-medullaire-non-traumatique-et-syndrome-de-la-queue-de-cheval\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 93 — compression médullaire et queue de cheval</a></li></ul></details>","frequence":1},{"id":"91-8","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes des déficits neurologiques récents périphériques","contenu":"<div class=\"notion-course\"><h4>Causes périphériques : raisonner sur le territoire</h4><table><thead><tr><th>Présentation</th><th>Causes et priorité</th></tr></thead><tbody><tr><td>Queue de cheval</td><td>Hernie lombaire, métastase, épidurite, autre compression : rechercher anesthésie en selle et troubles sphinctériens ; IRM urgente.</td></tr><tr><td>Déficit radiculaire</td><td>Compression d’une racine, notamment sciatique paralysante. Un déficit sévère ou progressif nécessite un avis spécialisé urgent.</td></tr><tr><td>Atteinte diffuse / polyradiculaire</td><td>Syndrome de Guillain-Barré ; méningoradiculites infectieuses ou néoplasiques. Rechercher extension, dysphagie, atteinte respiratoire et dysautonomie.</td></tr><tr><td>Plexopathie</td><td>Traumatisme, tumeur, syndrome de Parsonage-Turner.</td></tr><tr><td>Mononeuropathie multiple</td><td>Atteintes de plusieurs nerfs, souvent asymétriques : vascularite, diabète notamment.</td></tr><tr><td>Mononeuropathie</td><td>Compression traumatique ou posturale, cause ischémique. Si épisodes répétés après pression : évoquer une HNPP.</td></tr></tbody></table><h4>Ne pas fusionner les diagnostics</h4><p>Le Guillain-Barré n’est pas synonyme de toute méningoradiculite. Une atteinte sensitive distale est fréquente dans les neuropathies, mais une atteinte périphérique peut aussi être proximale ou motrice pure.</p><h4>Repère génétique corrigé</h4><p>La <span class=\"nc-red nc-bold\">neuropathie héréditaire avec hypersensibilité à la pression</span> (HNPP) est le plus souvent liée à une <strong>délétion de <span class=\"nc-pink nc-bold\">PMP22</span></strong> ; d’autres variants pathogènes existent. La duplication classique correspond à la maladie de Charcot-Marie-Tooth de type 1A.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Localisations et urgences complétées ; correction PMP22 confirmée par GeneReviews.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Items 95–97 — neuropathies et Guillain-Barré</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-7-item-93-compression-medullaire-non-traumatique-et-syndrome-de-la-queue-de-cheval\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 93 — compression médullaire et queue de cheval</a></li><li><a href=\"https://www.ncbi.nlm.nih.gov/sites/books/NBK1392/\" target=\"_blank\" rel=\"noopener noreferrer\">GeneReviews · HNPP — délétion ou variant pathogène de PMP22</a></li></ul></details>","frequence":0},{"id":"91-9","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","contenu":"<div class=\"notion-course\"><h4>Commencer par le caractère moteur pur</h4><p>Une atteinte motrice pure — <strong><span class=\"nc-green_bg\">pas de trouble sensitif, ni vésicosphinctérien</span></strong> — oriente vers la jonction neuromusculaire ou le muscle. Les ROT sont généralement conservés ; l’ensemble du tableau compte.</p><table><thead><tr><th>Jonction neuromusculaire</th><th>Muscle</th></tr></thead><tbody><tr><td><strong>Fatigabilité et fluctuation</strong>, aggravation à l’effort ; ptosis, diplopie, atteinte bulbaire ou proximale possibles.</td><td><strong><span class=\"nc-blue_bg\">Déficit à prédominance proximale</span></strong>, souvent bilatéral ; myalgies, amyotrophie ou urines foncées selon la cause.</td></tr><tr><td>Myasthénie et autres syndromes myasthéniques.</td><td>Myosite inflammatoire ou infectieuse, myopathie toxique ou métabolique (dyskaliémie), rhabdomyolyse.</td></tr><tr><td>ENMG avec stimulation répétitive ; anticorps anti-RACh / anti-MuSK selon la suspicion de myasthénie.</td><td>CK, ionogramme et fonction rénale selon le contexte ; ENMG pour caractériser l’atteinte.</td></tr></tbody></table><h4>Réponse idiomusculaire</h4><p>La disparition de la réponse idiomusculaire à la percussion directe est un argument <strong>myogène</strong>. Elle ne doit pas être présentée comme un signe commun à la myasthénie et aux myopathies.</p><h4>Gravité</h4><p>Dysphagie, voix qui s’épuise, toux inefficace, dyspnée ou orthopnée : évaluation hospitalière urgente. Ne pas attendre les anticorps ou l’ENMG pour sécuriser la respiration.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Jonction et muscle séparés ; signe idiomusculaire corrigé ; priorité respiratoire explicitée.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/myasthenie\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Myasthénie — signes bulbaires et respiratoires</a></li><li><a href=\"https://www.cen-neurologie.fr/premier-cycle/semiologie-analytique/syndrome-myogene-myopathique\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Sémiologie du syndrome myogène</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-6-item-92-deficit-moteur-etou-sensitif-des-membres\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 92 — sémiologie et examens ; figure 6.9</a></li></ul></details>","frequence":0},{"id":"91-10","rang":"A","rubrique":"Examens complémentaires","titre":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","contenu":"<div class=\"notion-course\"><h4>Hiérarchiser les examens non radiologiques</h4><table><thead><tr><th>Priorité</th><th>Examen</th><th>Ce qu’il apporte</th></tr></thead><tbody><tr><td>Immédiate</td><td>Glycémie capillaire</td><td>À mesurer devant tout déficit neurologique ; corriger une hypoglycémie et réévaluer.</td></tr><tr><td>En parallèle du bilan urgent</td><td>Biologie et ECG selon le contexte</td><td>Glycémie veineuse, NFS-plaquettes, ionogramme, créatinine, hémostase ; ECG si suspicion <span class=\"nc-orange_bg\">vasculaire</span>. Aucun bilan ne doit retarder l’imagerie urgente.</td></tr><tr><td>Orientée par la clinique</td><td>EEG</td><td>Suspicion de crise ou d’état de mal ; ne remplace pas l’imagerie devant un déficit aigu. Ne pas différer le traitement d’un état de mal convulsif pour attendre l’EEG.</td></tr><tr><td>Après évaluation de la gravité</td><td>ENMG</td><td>Racine, plexus, nerf, jonction neuromusculaire ou muscle. Ne doit pas retarder l’IRM d’une compression ni la prise en charge d’une défaillance respiratoire.</td></tr><tr><td>Après vérification des contre-indications</td><td>Ponction lombaire</td><td>Guillain-Barré, processus infectieux ou inflammatoire. Si déficit focal central : imagerie préalable. Une imagerie cérébrale n’est pas systématique pour toute neuropathie périphérique.</td></tr><tr><td>Ciblée</td><td>Autres prélèvements</td><td>Hémocultures et bilan infectieux si fièvre ; CK si atteinte musculaire ; toxiques et anticorps selon l’hypothèse.</td></tr></tbody></table><p>Dans un Guillain-Barré, l’hyperprotéinorachie peut être retardée : une PL précoce sans dissociation albumino-cytologique ne suffit pas à l’exclure.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Biologie élargie au contexte ; EEG et ENMG replacés après les priorités vitales ; PL conditionnelle précisée.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_830203/fr/accident-vasculaire-cerebral-prise-en-charge-precoce-alerte-phase-prehospitaliere-phase-hospitaliere-initiale-indications-de-la-thrombolyse\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Prise en charge précoce de l’AVC — actualisation partielle 2025</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-6-item-92-deficit-moteur-etou-sensitif-des-membres\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 92 — sémiologie et examens ; figure 6.9</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Items 95–97 — neuropathies et Guillain-Barré</a></li><li><a href=\"https://recospilf.infectiologie.com/pathologie/neuromeningees/encephalites-infectieuses/\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · Encéphalites infectieuses — version du 16/06/2026</a></li></ul></details>","frequence":0},{"id":"91-11","rang":"A","rubrique":"Identifier une urgence","titre":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","contenu":"<div class=\"notion-course\"><h4>Premières <span class=\"nc-pink nc-bold\">minutes</span></h4><ul><li><strong>Alerter et stabiliser :</strong> vigilance, respiration, circulation et déglutition ; surveillance des constantes. Appel au 15 hors de l’hôpital ou à l’équipe d’urgence sur place.</li><li><strong>Mesurer la glycémie</strong> immédiatement ; traiter l’hypoglycémie sans retarder les autres gestes. Pas d’apport oral si conscience ou déglutition altérée.</li><li><strong>Documenter :</strong> heure de début / dernière heure sans déficit, examen neurologique, traitements dont anticoagulants et évolution.</li></ul><table><thead><tr><th>Contexte</th><th>Marche à suivre</th></tr></thead><tbody><tr><td>AVC ou AIT suspecté</td><td>Filière neurovasculaire et imagerie cérébrale / artérielle immédiates. Un déficit régressif, un réveil avec déficit ou un horaire inconnu restent urgents. La décision de reperfusion relève de l’équipe spécialisée.</td></tr><tr><td>Traumatisme crânien</td><td>TDM sans injection immédiate ; stabilisation et avis neurochirurgical urgent. L’indication d’évacuation dépend des lésions et de l’état clinique.</td></tr><tr><td>Fièvre et déficit focal</td><td>Hémocultures, imagerie urgente avant PL si indiquée. Si suspicion de méningite / encéphalite, commencer le traitement probabiliste adapté sans attendre une imagerie ou une PL retardée.</td></tr><tr><td>Syndrome médullaire / queue de cheval</td><td>IRM urgente pour rechercher une compression et avis chirurgical sans délai. Sans compression : enquête <span class=\"nc-orange_bg\">vasculaire</span>, inflammatoire ou infectieuse spécialisée.</td></tr><tr><td>Paralysie extensive / signes bulbaires</td><td>Suspecter notamment Guillain-Barré ou crise myasthénique : surveillance respiratoire et hémodynamique rapprochée, avis réanimation ; bilan étiologique en parallèle.</td></tr><tr><td>Crise prolongée / état de mal</td><td>Traitement anticonvulsivant urgent selon protocole ; EEG pour préciser ou surveiller, sans attendre devant un état de mal convulsif clinique.</td></tr><tr><td>Hypoglycémie / carence</td><td>Corriger l’hypoglycémie puis réexaminer. Si risque de Gayet-Wernicke : thiamine parentérale précoce, sans retarder le glucose nécessaire.</td></tr></tbody></table><h4>Après la phase aiguë</h4><p>Organiser la rééducation adaptée (kinésithérapie, orthophonie…), l’évaluation de la déglutition, la prévention des complications et le traitement de la cause. Plusieurs urgences peuvent coexister.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Conduites urgentes complétées ; les examens de confirmation ne retardent plus les traitements prioritaires. Repère : le CEN préconise la B1 avant les apports glucosés chez le patient carencé ; en hypoglycémie urgente, les recommandations ASAM permettent une administration concomitante pour ne pas retarder le resucrage.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_830203/fr/accident-vasculaire-cerebral-prise-en-charge-precoce-alerte-phase-prehospitaliere-phase-hospitaliere-initiale-indications-de-la-thrombolyse\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Prise en charge précoce de l’AVC — actualisation partielle 2025</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-7-item-93-compression-medullaire-non-traumatique-et-syndrome-de-la-queue-de-cheval\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 93 — compression médullaire et queue de cheval</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/myasthenie\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Myasthénie — signes bulbaires et respiratoires</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-8-item-95-radiculalgies-et-syndromes-canalaires-item-96-neuropathies-peripheriques-item-97-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Items 95–97 — neuropathies et Guillain-Barré</a></li><li><a href=\"https://recospilf.infectiologie.com/pathologie/neuromeningees/encephalites-infectieuses/\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · Encéphalites infectieuses — version du 16/06/2026</a></li><li><a href=\"https://recospilf.infectiologie.com/pathologie/neuromeningees/meningites-bacteriennes-aigues-communautaires-a-lexclusion-du-nouveau-ne/\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · Méningites bactériennes — version du 05/05/2026</a></li><li><a href=\"https://downloads.asam.org/sitefinity-production-blobs/docs/default-source/guidelines/awg-3-20-20.pdf?sfvrsn=d87852c2_2\" target=\"_blank\" rel=\"noopener noreferrer\">ASAM · Guideline 2020, V.7 — glucose et thiamine sans retard de traitement</a></li></ul></details>","frequence":1},{"id":"91-12","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes de déficit neurologique récent transitoire","contenu":"<div class=\"notion-course\"><h4>Déficit disparu : l’interrogatoire devient central</h4><p>Reconstituer symptômes, début, durée, succession et récupération avec le patient et les témoins. La disparition des signes ne rassure pas à elle seule.</p><table><thead><tr><th>Repère</th><th>AIT</th><th>Crise <span class=\"nc-orange_bg\">épileptique</span></th><th>Aura <span class=\"nc-orange_bg\">migraineuse</span></th></tr></thead><tbody><tr><td>Installation</td><td>Brutal, souvent d’<span class=\"nc-pink nc-bold\">emblée maximal</span>.</td><td><span class=\"nc-pink nc-bold\">Secondes</span> ; accès stéréotypé, éventuelle marche <span class=\"nc-orange_bg\">épileptique</span>.</td><td>Progression sur plusieurs <span class=\"nc-pink nc-bold\">minutes</span>, succession possible de symptômes.</td></tr><tr><td>Manifestations</td><td>Souvent négatives : perte de force, sensibilité, vision ou langage.</td><td>Signes positifs possibles : clonies, paresthésies, hallucinations ; puis déficit postcritique possible.</td><td>Phénomènes visuels lumineux ou colorés, scotome scintillant ; symptômes sensitifs ou du langage possibles.</td></tr><tr><td>Contexte</td><td>Facteurs vasculaires fréquents, mais possible à tout âge.</td><td>Épilepsie connue ou premier épisode ; possible à tout âge.</td><td>Antécédents de migraine ; céphalée souvent associée, parfois absente.</td></tr><tr><td>Évolution</td><td>Régression souvent rapide. La définition repose sur l’absence d’infarctus aigu, pas sur un seuil isolé de durée.</td><td>Crise généralement brève ; déficit postcritique parfois plus prolongé.</td><td>Chaque symptôme typique dure habituellement 5 à 60 min ; certaines formes sont plus longues.</td></tr></tbody></table><h4>Autres possibilités</h4><ul><li><strong>Hypoglycémie :</strong> glycémie capillaire devant tout déficit, même sans diabète connu.</li><li><strong>Lésion cérébrale :</strong> <span class=\"nc-orange_bg\">hématome sous-dural</span>, <span class=\"nc-orange_bg\">tumeur cérébrale</span> ou <span class=\"nc-orange_bg\">malformation vasculaire</span> ; un épisode peut correspondre à une crise surajoutée.</li><li><strong>Compression nerveuse :</strong> <span class=\"nc-orange_bg\">atteinte périphérique tronculaire par compression posturale ou externe</span> ; récidives après pression : rechercher une HNPP (délétion de <span class=\"nc-pink nc-bold\">PMP22</span> le plus souvent).</li></ul><h4>Conduite</h4><p>Un déficit brutal transitoire nécessite une évaluation neurovasculaire urgente. Une première aura, une présentation atypique ou une incertitude justifient une évaluation ; les profils du tableau ne sont pas des critères d’exclusion absolus.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Définition de l’AIT et profils temporels précisés ; correction PMP22 ; âge et récupération ne servent pas à exclure une urgence.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Item 91</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-5-item-91-deficit-neurologique-recent\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 91 — déficit neurologique récent</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_830203/fr/accident-vasculaire-cerebral-prise-en-charge-precoce-alerte-phase-prehospitaliere-phase-hospitaliere-initiale-indications-de-la-thrombolyse\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Prise en charge précoce de l’AVC — actualisation partielle 2025</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-28-item-340-accidents-vasculaires-cerebraux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 340 — AVC et définition de l’AIT</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 99 — critères temporels de l’aura</a></li><li><a href=\"https://www.ncbi.nlm.nih.gov/sites/books/NBK1392/\" target=\"_blank\" rel=\"noopener noreferrer\">GeneReviews · HNPP — délétion ou variant pathogène de PMP22</a></li></ul></details>","frequence":0}],"astuces":[{"type":"warning","titre":"Déficit disparu ≠ urgence disparue","contenu":"<div class=\"notion-course\"><p>Un AIT suspecté exige une évaluation urgente. Reconstituer l’épisode avec les témoins et ne pas attendre une récidive.</p></div>"},{"type":"info","titre":"Les réflexes peuvent tromper au début","contenu":"<div class=\"notion-course\"><p>Une atteinte <span class=\"nc-orange nc-bold\">centrale</span> aiguë peut être flasque avec ROT diminués. À l’inverse, l’amyotrophie périphérique peut être tardive.</p></div>"},{"type":"info","titre":"Deux arbres, deux usages","contenu":"<div class=\"notion-course\"><p>Le parcours des urgences organise les premiers gestes. L’arbre adapté de la figure 6.9 du CEN aide à choisir les examens après localisation.</p></div>"},{"type":"warning","titre":"PMP22 : correction à retenir","contenu":"<div class=\"notion-course\"><p>HNPP : <strong>délétion</strong> le plus souvent. CMT1A : <strong>duplication</strong>.</p></div>"}],"strategie":{"urgence":"<div class=\"notion-course\"><ul><li>Mesurer la glycémie ; évaluer vigilance, respiration, circulation et déglutition.</li><li>Déficit brutal ou transitoire : filière neurovasculaire et imagerie immédiates.</li><li>Traumatisme crânien : TDM sans injection ; syndrome médullaire / queue de cheval : IRM urgente.</li><li>Ne pas retarder les soins vitaux pour l’ENMG, les anticorps ou la PL.</li></ul></div>","hospit":"<div class=\"notion-course\"><ul><li>Orientation selon la cause : unité neurovasculaire, neurochirurgie, neurologie ou infectiologie.</li><li>Avis réanimation si atteinte respiratoire, bulbaire sévère, hémodynamique ou trouble de conscience.</li><li>Un déficit récent inexpliqué nécessite une évaluation rapide ; une régression ne suffit pas à autoriser une simple surveillance.</li></ul></div>","redflags":"<div class=\"notion-course\"><ul><li>Début brutal, y compris avec récupération.</li><li>Vigilance, déglutition, respiration ou hémodynamique altérées.</li><li>Déficit post-traumatique ou fébrile.</li><li>Niveau sensitif, anesthésie en selle ou troubles sphinctériens.</li><li>Paralysie extensive ou aggravation rapide.</li></ul></div>","principes":"<div class=\"notion-course\"><ul><li>Caractériser → localiser → identifier le mécanisme, en parallèle des gestes urgents.</li><li>Imagerie selon la topographie ; ENMG, EEG, LCS et biologie selon les hypothèses.</li><li>Rééducation et prévention des complications après stabilisation.</li><li>Les références et corrections sont détaillées sous chaque objectif.</li></ul></div>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/deficit-neurologique-recent","label":"Collège CEN — Déficit neurologique récent"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Évaluer et mesurer la glycémie","detail":"<ul><li>Vérifier vigilance, respiration, circulation et déglutition.</li><li>Noter début des signes ou dernière heure sans déficit.</li><li>Mesurer la glycémie capillaire sans retarder les gestes de secours.</li><li>Si plusieurs alertes coexistent, mener stabilisation, resucrage et recherche de la cause en parallèle.</li></ul>","branches":[{"label":"Défaillance ou menace vitale","to":"vital"},{"label":"Hypoglycémie identifiée","to":"hypo"},{"label":"Pas de défaillance ni hypoglycémie","to":"orientation"}]},{"id":"vital","kind":"urgent","label":"Alerter et sécuriser les fonctions vitales","detail":"<ul><li>Appeler l’équipe d’urgence ; surveiller les constantes.</li><li>Protéger la respiration ; pas d’apport oral si déglutition altérée.</li><li>Rechercher en parallèle AVC, état de mal, infection et atteinte neuromusculaire extensive.</li><li>Ne pas attendre les examens de confirmation pour traiter la défaillance.</li></ul>","branches":[]},{"id":"hypo","kind":"urgent","label":"Corriger l’hypoglycémie et réexaminer","detail":"<ul><li>Resucrer par une voie adaptée à la conscience et à la déglutition.</li><li>Recontrôler la glycémie et le déficit.</li><li>Persistance ou incertitude : poursuivre immédiatement la recherche d’une cause associée, notamment un AVC.</li><li>Prévenir la récidive et rechercher la cause de l’hypoglycémie.</li></ul>","branches":[]},{"id":"orientation","kind":"decision","label":"Préciser le début et les signes associés","detail":"<ul><li>Reconstituer l’épisode, même s’il est terminé.</li><li>Chercher traumatisme, fièvre, douleur rachidienne et extension.</li><li>Les branches indiquent des priorités et ne rendent pas les causes mutuellement exclusives.</li></ul>","branches":[{"label":"Brutal, transitoire ou horaire inconnu","to":"avc"},{"label":"Contexte ou signe d’alerte particulier","to":"contexte"},{"label":"Progressif sans alerte identifiée","to":"localiser"}]},{"id":"avc","kind":"urgent","label":"Activer la filière neurovasculaire","detail":"<ul><li>Appeler le 15 ou l’équipe neurovasculaire.</li><li>Obtenir l’imagerie cérébrale et artérielle urgente.</li><li>La régression des signes n’autorise pas l’attente. Ne pas exclure un AVC sur l’âge ou une présentation au réveil.</li><li>L’équipe spécialisée décide du traitement après l’imagerie.</li></ul>","branches":[]},{"id":"contexte","kind":"decision","label":"Choisir l’exploration urgente adaptée","detail":"<ul><li>Repérer le contexte dominant et les autres alertes.</li><li>Ne pas attribuer tous les signes à une seule cause trop vite.</li><li>Un déficit aigu reste urgent même en l’absence de détresse vitale.</li><li>Si la présentation demeure incertaine, obtenir un avis neurologique urgent et une imagerie adaptée.</li></ul>","branches":[{"label":"Après traumatisme crânien","to":"trauma"},{"label":"Fièvre ou syndrome méningé","to":"infection"},{"label":"Niveau sensitif, selle ou sphincters","to":"compression"},{"label":"Paralysie extensive ou signes bulbaires","to":"extension"}]},{"id":"trauma","kind":"urgent","label":"Faire une TDM cérébrale immédiate","detail":"<ul><li>Demander une TDM cérébrale sans injection.</li><li>Organiser l’avis neurochirurgical selon les lésions.</li><li>Rechercher hématome extradural, sous-dural aigu et contusion.</li><li>Stabiliser le patient pendant le bilan et le transfert.</li></ul>","branches":[]},{"id":"infection","kind":"urgent","label":"Explorer et traiter l’infection suspectée","detail":"<ul><li>Prélever les hémocultures et obtenir l’imagerie urgente.</li><li>Si déficit focal central : évaluer l’imagerie avant la PL.</li><li>Le traitement probabiliste adapté ne doit pas attendre une imagerie ou une PL retardée.</li><li>Rechercher encéphalite, méningite, abcès et autres causes du déficit.</li></ul>","branches":[]},{"id":"compression","kind":"urgent","label":"Rechercher une compression en urgence","detail":"<ul><li>Obtenir l’IRM médullaire ou lombosacrée selon les signes.</li><li>Demander un avis chirurgical si compression.</li><li>Niveau sensitif : penser moelle. Anesthésie en selle et troubles sphinctériens : penser queue de cheval.</li><li>Sans compression, poursuivre le bilan vasculaire, inflammatoire ou infectieux.</li></ul>","branches":[]},{"id":"extension","kind":"urgent","label":"Surveiller respiration et dysautonomie","detail":"<ul><li>Rechercher dysphagie, toux inefficace et dyspnée.</li><li>Hospitaliser ; avis réanimation selon la gravité.</li><li>Évoquer Guillain-Barré et myasthénie selon les signes.</li><li>ENMG, LCS ou anticorps complètent le bilan sans retarder les soins.</li></ul>","branches":[]},{"id":"localiser","kind":"decision","label":"Localiser puis choisir les examens","detail":"<ul><li>Examiner force, sensibilité, réflexes, langage et nerfs crâniens.</li><li>Consulter l’arbre des examens du CEN dans cet onglet.</li><li>Exploration rapide même si l’installation est progressive ; réévaluation immédiate si aggravation.</li></ul>","branches":[{"label":"Arguments centraux","to":"central"},{"label":"Nerf, jonction ou muscle probable","to":"peripherique"},{"label":"Autre cause ou présentation discordante","to":"autre"}]},{"id":"central","kind":"finish","label":"Explorer l’encéphale ou la moelle","detail":"<ul><li>Demander l’imagerie orientée par la topographie.</li><li>Confronter au terrain et au profil évolutif.</li><li>Ne pas conclure à une origine périphérique sur des ROT diminués isolés à la phase aiguë.</li></ul>","branches":[]},{"id":"peripherique","kind":"finish","label":"Explorer le nerf, la jonction ou le muscle","detail":"<ul><li>Organiser l’ENMG ciblé et les examens associés.</li><li>Rechercher une extension ou une atteinte respiratoire.</li><li>CK si atteinte musculaire ; LCS si polyradiculonévrite ou inflammation selon la clinique.</li></ul>","branches":[]},{"id":"autre","kind":"uncertain","label":"Vérifier les diagnostics différentiels","detail":"<ul><li>Examiner articulations, pouls et fonctions sensorielles.</li><li>Rechercher des signes positifs si TNF envisagé.</li><li>Une présentation discordante ne justifie pas d’arrêter le bilan urgent.</li><li>Le diagnostic fonctionnel doit être expliqué et peut coexister avec une autre maladie.</li></ul>","branches":[]}]},"cards":[{"i":"3fcd41b0b5da","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Quelle est la définition d'un déficit neurologique focal ?","a":"<p>Perte d’une fonction localisée à une région du système nerveux : par exemple force d’un hémicorps, langage ou champ visuel. Elle peut être transitoire ou persistante.</p>"},{"i":"40d08a3b05f5","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Qu'est-ce qui caractérise une souffrance cérébrale diffuse ?","a":"<p>Altération globale pouvant se manifester par une perte de connaissance, un coma ou une confusion. Un déficit focal peut néanmoins coexister : il faut le rechercher.</p>"},{"i":"4948d705cd46","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Quelle est la définition d'un déficit neurologique ?","a":"<p>C'est une <strong>dysfonction</strong>, temporaire ou lésionnelle, d'une région du <strong>système nerveux</strong>.</p>"},{"i":"f98660e2a329","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Comment définit-on un déficit neurologique récent ?","a":"<p>Un déficit neurologique est qualifié de récent s'il est apparu depuis <strong>moins d'un mois</strong>.</p>"},{"i":"0fbf9512f7f4","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Dans quel contexte et quels examens sont inclus dans le bilan biologique devant un déficit neurologique récent ?","a":"<ul><li>Bilan adapté à la suspicion : glycémie, NFS-plaquettes, ionogramme, créatinine, hémostase notamment en contexte vasculaire.</li><li>Si infection : hémocultures, marqueurs inflammatoires et prélèvements ciblés.</li><li>CK si atteinte musculaire ; autres examens selon l’hypothèse. Ne pas retarder l’imagerie urgente.</li></ul>"},{"i":"397c3f702dd9","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Quelle est l'indication et la priorité de la glycémie capillaire devant un déficit neurologique récent ?","a":"<p>La glycémie capillaire est indiquée devant <strong>tout déficit neurologique</strong>. C'est un examen de <strong>priorité absolue</strong> car une hypoglycémie peut mimer n'importe quel signe focal et donner des signes neurologiques trompeurs.</p>"},{"i":"6d1ea9a0cfcd","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Quelles sont les principales indications d'une ponction lombaire (PL) devant un déficit neurologique récent, et quand doit-elle être réalisée ?","a":"<ul><li>Indications : polyradiculonévrite, maladie infectieuse ou inflammatoire.</li><li>Vérifier les contre-indications. Un déficit focal central impose l’imagerie préalable ; rechercher une compression si syndrome médullaire.</li><li>L’imagerie cérébrale n’est pas systématique avant toute PL pour neuropathie. Ne pas retarder un traitement anti-infectieux urgent.</li></ul>"},{"i":"ace268320c8b","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Quand l'EMG est-il indiqué devant un déficit neurologique récent et quelle est sa priorité ?","a":"<p>L’ENMG explore le nerf périphérique, la jonction neuromusculaire et le muscle. Il ne doit pas retarder l’IRM d’une compression ni la prise en charge respiratoire d’une paralysie extensive.</p>"},{"i":"f7a43ec3799d","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Dans quel contexte et avec quelle priorité l'EEG est-il indiqué devant un déficit neurologique récent ?","a":"<p>En cas de suspicion de crise ou d’état de mal. Il ne remplace pas l’imagerie d’un déficit aigu et ne doit pas retarder le traitement d’un état de mal convulsif clinique.</p>"},{"i":"45da925dee58","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Quels sont les signes de gravité à rechercher en présence d'un déficit neurologique récent, justifiant une prise en charge immédiate ?","a":"<p>Les signes de gravité justifiant une prise en charge immédiate en présence d'un déficit neurologique récent sont :</p><ul><li>Des <strong>troubles de la vigilance</strong>.</li><li>Des <strong>troubles de la déglutition</strong>.</li><li>Une <strong>atteinte respiratoire</strong>.</li><li>Une <strong>atteinte hémodynamique</strong>.</li></ul>"},{"i":"7a91e55d6be2","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Quelles sont les étiologies métaboliques urgentes à rechercher en cas de déficit neurologique ?","a":"<p>Les étiologies métaboliques urgentes à rechercher sont :</p><ul><li>L'<strong>hypoglycémie</strong>, confirmée par une glycémie capillaire et à corriger en urgence.</li><li>L'<strong>encéphalopathie de Gayet-Wernicke</strong>, cause carentielle.</li></ul>"},{"i":"7b639a093770","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Face à un déficit neurologique d'origine infectieuse, quelles sont les causes à évoquer et les bilans à réaliser ?","a":"<ul><li>Évoquer méningo-encéphalite et abcès cérébral devant un déficit fébrile.</li><li>Hémocultures et bilan ciblé ; imagerie urgente avant la PL en présence d’un déficit focal central.</li><li>Traitement probabiliste adapté en urgence : ne pas attendre des examens retardés.</li></ul>"},{"i":"ab77f117f559","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Comment prendre en charge un syndrome médullaire aigu ou de la queue de cheval ?","a":"<ul><li>IRM urgente : médullaire ou lombosacrée selon les signes.</li><li>Compression : avis chirurgical urgent et traitement adapté.</li><li>Sans compression : rechercher myélite, infarctus ou autre cause ; PL selon l’indication.</li><li>Évoquer une dissection aortique selon le contexte d’un infarctus médullaire.</li></ul>"},{"i":"b594e676ea12","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Quelles sont les autres urgences neurologiques non encore citées pouvant provoquer un déficit neurologique récent ?","a":"<ul><li>AVC : imagerie et filière neurovasculaire immédiates.</li><li>État de mal épileptique : traitement urgent ; ne pas attendre l’EEG devant un état de mal convulsif clinique.</li></ul>"},{"i":"b5eb45be14e0","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"En cas de déficit neurologique traumatique, quel est l'examen d'imagerie clé et que recherche-t-il ?","a":"<p>En cas de déficit neurologique traumatique, l'examen d'imagerie clé est une <strong>TDM cérébrale sans injection en urgence</strong>. Elle permet de rechercher un <strong>hématome extra-dural (HED)</strong> ou un <strong>hématome sous-dural aigu (HSDA)</strong>.</p>"},{"i":"c8579fc491f7","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Devant un déficit neurologique récent périphérique extensif, quelles urgences diagnostiques doivent être recherchées ?","a":"<ul><li>Guillain-Barré et crise myasthénique notamment.</li><li>Priorité : déglutition, respiration et stabilité hémodynamique ; hospitalisation et avis réanimation selon la gravité.</li><li>ENMG, étude du LCS ou anticorps précisent le diagnostic sans retarder les soins.</li></ul>"},{"i":"133abb0ed986","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Quelles sont les autres causes de déficit neurologique transitoire, en dehors de l'AIT, de la crise d'épilepsie et de l'aura migraineuse ?","a":"<ul><li>Hypoglycémie : mesurer la glycémie immédiatement.</li><li>Lésion cérébrale (hématome sous-dural, tumeur, malformation), souvent avec crise surajoutée.</li><li>Compression d’un nerf ; si récidives après pression, évoquer la HNPP, le plus souvent liée à une <strong>délétion de PMP22</strong>.</li></ul>"},{"i":"5b4da5b1ebf2","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Quelle est la définition d'un Accident Ischémique Transitoire (AIT) et ses caractéristiques cliniques principales ?","a":"<p>Épisode transitoire de dysfonction neurologique par ischémie focale, <strong>sans infarctus aigu</strong>. Le début est souvent brutal ; les symptômes sont souvent négatifs. La durée est typiquement brève mais ne suffit pas à définir l’AIT. C’est une urgence neurovasculaire même après régression.</p>"},{"i":"784b608d6846","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Comment différencier cliniquement une crise d'épilepsie d'un Accident Ischémique Transitoire (AIT) ou d'une aura migraineuse sur la base de l'installation des symptômes ?","a":"<ul><li>AIT : début souvent brutal, d’emblée maximal.</li><li>Crise : secondes, accès stéréotypé ; un déficit postcritique peut persister.</li><li>Aura : progression sur des minutes, parfois plusieurs symptômes successifs.</li><li>Ces profils orientent sans exclure à eux seuls une cause vasculaire.</li></ul>"},{"i":"bfec30eb4f6e","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Quels sont les signes associés et le terrain évocateur d'une aura migraineuse comparé à une crise d'épilepsie ou un AIT ?","a":"<ul><li>Aura : phénomènes visuels ou sensitifs, progression, antécédents migraineux ; céphalée possible mais non obligatoire.</li><li>Crise : clonies, rupture de contact ou amnésie ; antécédents possibles, à tout âge.</li><li>AIT : facteurs vasculaires fréquents, mais possible aussi chez le sujet jeune.</li></ul>"},{"i":"20fc4dfdb7d2","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Comment différencier cliniquement une occlusion artérielle aiguë d'un déficit neurologique récent chez un patient présentant un membre déficitaire ?","a":"<p>Douleur, froideur, pâleur et pouls diminués ou absents orientent vers une ischémie de membre. Un déficit sensitivo-moteur est un signe de gravité : avis vasculaire urgent. La douleur seule ne tranche pas.</p>"},{"i":"46d64ce8c594","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Quelles sont les principales caractéristiques cliniques qui orientent vers une impotence fonctionnelle d'origine ostéo-articulaire plutôt qu'un déficit neurologique récent ?","a":"<p>Douleur et limitation articulaire au premier plan, contexte de fracture, entorse, arthrite ou rupture de coiffe. Confronter examen articulaire et examen neurologique ; la douleur seule n’exclut pas une cause neurologique.</p>"},{"i":"4974d5d5d9c0","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Sur quoi repose le diagnostic d’un trouble neurologique fonctionnel devant un déficit récent ?","a":"<p>Signes positifs d’inconsistance entre gestes volontaires et automatiques, par exemple Hoover. Une imagerie normale ou un contexte anxieux ne suffisent pas. Un TNF n’est pas une simulation et peut coexister avec une autre maladie.</p>"},{"i":"f41e13e4db8f","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Quels sont les déficits non neurologiques pouvant mimer des troubles neurologiques mais étant d'origine ORL ou ophtalmologique ?","a":"<p>Une cause laryngée peut expliquer une dysphonie ; une atteinte vestibulaire un trouble de l’équilibre ; une cause oculaire un trouble visuel. Distinguer ces tableaux d’une aphasie, d’une ataxie centrale ou d’une atteinte des voies visuelles. Un début brutal impose une évaluation urgente adaptée.</p>"},{"i":"019e04e2fdc3","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les arguments cliniques majeurs suggérant un déficit neurologique récent d'origine centrale au niveau du Système Nerveux Central (SNC) ?","a":"<p>Les arguments cliniques majeurs pour un déficit neurologique récent d'origine centrale au niveau du SNC incluent :</p><ul><li>Une <strong>atteinte d'un hémicorps</strong> (hémiplégie ou hémiparésie).</li><li>Des signes pyramidaux : <strong>ROT vifs</strong>, <strong>clonus de cheville</strong>, <strong>signe de Babinski</strong>.</li><li>Un <strong>niveau sensitif thoracique ou abdominal franc</strong>.</li><li>Des signes associés : <strong>aphasie</strong>, <strong>hémianopsie latérale homonyme (HLH)</strong>, troubles gnosiques.</li><li>La présence de <strong>troubles de la vigilance</strong>, de <strong>crises d'épilepsie</strong> ou d'une atteinte des paires crâniennes avec atteinte des voies longues.</li></ul>"},{"i":"070eed19847f","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Comment distinguer cliniquement un déficit neurologique d'origine centrale (pyramidale) d'une atteinte périphérique (système nerveux périphérique) ?","a":"<ul><li>Central : signes pyramidaux, hémicorps, signes corticaux ou niveau sensitif.</li><li>Périphérique : territoire radiculaire ou tronculaire, diminution des ROT, amyotrophie parfois tardive.</li><li>Piège : une lésion centrale aiguë peut être flasque et aréflexique ; une queue de cheval peut donner des troubles sphinctériens.</li></ul>"},{"i":"0726f1463b2f","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les examens paracliniques de première intention pour explorer un déficit neurologique récent suspecté d'origine centrale ?","a":"<p>Pour explorer un déficit neurologique récent d'origine centrale, les examens paracliniques de première intention sont :</p><ul><li>Une <strong>IRM cérébrale</strong> (ou TDM cérébrale à défaut) en cas de suspicion d'atteinte cérébrale.</li><li>Une <strong>Angio-IRM</strong> ou <strong>Angio-TDM cervico-encéphalique</strong> en cas de forte suspicion d'accident vasculaire cérébral (AVC).</li><li>Une <strong>IRM cervico-dorso-lombaire</strong> en cas de suspicion de pathologie médullaire.</li><li>Un <strong>EEG</strong> en cas de suspicion d'épilepsie.</li></ul>"},{"i":"2fbb22b6e1be","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les arguments cliniques orientant vers une atteinte du Système Nerveux Périphérique (SNP) dans le cadre d'un déficit neurologique récent ?","a":"<ul><li>Topographie radiculaire, plexique ou tronculaire ; atteinte d’un ou plusieurs nerfs.</li><li>ROT diminués selon les territoires, amyotrophie et fasciculations possibles mais non obligatoires au début.</li><li>Atteinte distale fréquente, mais formes proximales possibles. Troubles sphinctériens possibles dans une queue de cheval.</li></ul>"},{"i":"6b7449bab610","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les arguments cliniques spécifiques suggérant une atteinte de la plaque motrice ou du muscle lui-même (myopathie/myasthénie) face à un déficit moteur ?","a":"<ul><li>Atteinte motrice pure, sans trouble sensitif ni vésicosphinctérien ; déficit souvent proximal.</li><li>Fatigabilité / fluctuation et signes oculobulbaires : penser jonction neuromusculaire.</li><li>Myalgies, déficit proximal bilatéral et réponse idiomusculaire diminuée : penser muscle.</li><li>La disparition de la réponse idiomusculaire n’est pas un signe de myasthénie.</li></ul>"},{"i":"9ca8fb67caa4","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels examens paracliniques sont utiles pour confirmer un déficit neurologique récent d'origine périphérique ?","a":"<p>Pour confirmer un déficit neurologique récent d'origine périphérique, les examens utiles sont :</p><ul><li>L'<strong>électromyogramme (EMG)</strong> pour évaluer l'atteinte du nerf et/ou du muscle.</li><li>Une <strong>IRM lombaire</strong> en cas de suspicion d'atteinte de la queue de cheval.</li><li>Une <strong>ponction lombaire (PL)</strong> pour rechercher une inflammation (polyradiculonévrite, processus infectieux ou inflammatoire).</li></ul>"},{"i":"126015d10048","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quelle est l'attitude d'urgence devant un déficit neurologique brutal d'emblée maximal ?","a":"<p>Devant un déficit neurologique <strong>brutal d'emblée maximal</strong>, il faut suspecter un <strong>AVC</strong> jusqu'à preuve du contraire, ce qui impose la réalisation d'une <strong>imagerie cérébrale en urgence</strong> (IRM ou scanner selon la disponibilité).</p>"},{"i":"12ecc7c8869f","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quels sont les mécanismes à considérer devant un déficit neurologique d'installation aiguë ou subaiguë (heures à jours) ?","a":"<p>Devant un déficit neurologique d'installation <strong>aiguë ou subaiguë</strong> (heures à jours), les mécanismes à considérer sont :</p><ul><li><strong>Inflammatoire</strong>.</li><li><strong>Infectieux</strong>.</li><li><strong>Toxique</strong>.</li><li>Un mécanisme <strong>vasculaire lent</strong> (thrombophlébite cérébrale, thrombose artérielle in situ).</li></ul>"},{"i":"66173e25088d","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quelle est la signification d'une évolution en \"tache d'huile\" ou rapidement progressive sur quelques semaines pour un déficit neurologique ?","a":"<p>Une évolution en \"tache d'huile\" ou rapidement progressive sur quelques semaines, caractérisée par une <strong>aggravation progressive</strong> du déficit neurologique, doit faire évoquer un <strong>processus expansif</strong> tel qu'une tumeur maligne, un abcès, ou un hématome sous-dural. D'autres causes comme infectieuses ou métaboliques sont aussi possibles.</p>"},{"i":"a35a8570c208","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quelles sont les trois étapes séquentielles de la démarche diagnostique devant un déficit neurologique récent ?","a":"<ul><li>Caractériser les fonctions atteintes.</li><li>Localiser le syndrome.</li><li>Identifier le mécanisme à partir de la temporalité, du contexte et des examens ciblés.</li><li>En parallèle, dès le départ : gravité et glycémie.</li></ul>"},{"i":"aa9474f94a1d","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Comment est orienté le diagnostic en cas de déficit neurologique transitoire, où l'examen clinique est normal au moment de la consultation ?","a":"<p>Reconstituer l’épisode auprès du patient et des témoins : début, symptômes, succession, durée et récupération. Un examen redevenu normal n’exclut pas l’AIT et ne supprime pas l’urgence.</p>"},{"i":"d8e0498e995d","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quel mécanisme doit être prioritairement évoqué devant un déficit neurologique d'installation brutale (secondes à minutes) et d'emblée maximal ?","a":"<p>Devant un déficit neurologique d'installation <strong>brutale</strong> (secondes à minutes) et <strong>d'emblée maximal</strong>, un mécanisme <strong>vasculaire</strong>, notamment un <strong>AVC</strong>, doit être évoqué en priorité jusqu'à preuve du contraire.</p>"},{"i":"0477a81c5b38","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Quand faut-il envisager une Angio-IRM ou une Angio-TDM cervico-encéphalique face à un déficit neurologique récent ?","a":"<p>Ces examens sont indiqués en cas de <strong>suspicion d'infarctus cérébral</strong> (occlusion artérielle) afin de rechercher une <strong>sténose ou une occlusion</strong>.</p>"},{"i":"58693bdcd8da","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Quand l'IRM médullaire est-elle préconisée devant un déficit neurologique récent ?","a":"<p>L'IRM médullaire est préconisée en cas de <strong>syndrome médullaire</strong> ou de <strong>syndrome de la queue de cheval</strong>.</p>"},{"i":"a3c655a36355","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Dans quelles situations spécifiques la TDM cérébrale est-elle indiquée en première intention ou en l'absence d'IRM lors d'un déficit neurologique récent ?","a":"<p>La TDM cérébrale est indiquée en l'absence d'IRM, ou en urgence, notamment en cas de <strong>traumatisme</strong> ou de suspicion d'<strong>hémorragie</strong>. Elle est réalisée <strong>sans injection</strong> en première intention.</p>"},{"i":"ef2c85162d2e","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Quelle est l'indication principale de l'IRM cérébrale devant un déficit neurologique récent, selon l'objectif EDN ?","a":"<p>Suspicion d’atteinte <strong>encéphalique</strong> (cerveau ou tronc cérébral), selon l’urgence et la disponibilité. Une atteinte médullaire haute relève d’une IRM de la moelle.</p>"},{"i":"140abec92df5","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les étiologies traumatiques à considérer en cas de déficit neurologique récent d'origine encéphalique ?","a":"<ul><li>Hématome extradural.</li><li>Hématome sous-dural traumatique.</li><li>Contusion cérébrale.</li><li>Un sous-dural peut également être spontané : il ne s’agit alors pas d’une cause traumatique.</li></ul>"},{"i":"1b1828c4e7ae","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes vasculaires de déficit neurologique récent d'origine encéphalique ?","a":"Les causes vasculaires d'atteinte encéphalique comprennent :<ul><li>L'<strong>infarctus cérébral</strong>.</li><li>L'<strong>hémorragie intraparenchymateuse</strong>.</li><li>La <strong>thrombose veineuse cérébrale</strong>.</li><li>L'<strong>hémorragie méningée</strong>.</li></ul>"},{"i":"3ee53eda2755","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les principales causes compressives de déficit neurologique récent d'origine médullaire ?","a":"Les causes compressives médullaires sont :<ul><li>D'origine <strong>traumatique</strong>.</li><li>D'origine <strong>néoplasique</strong>.</li><li>La <strong>spondylodiscite ou épidurite infectieuse</strong>.</li><li>La <strong>hernie discale</strong>.</li><li>L'<strong>hématome épidural</strong>.</li></ul>"},{"i":"69b1f7e6e1a6","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes tumorales et infectieuses de déficit neurologique récent d'origine encéphalique ?","a":"Les causes tumorales sont :<ul><li>La <strong>tumeur gliale</strong>.</li><li>Les <strong>métastases cérébrales</strong>.</li><li>Le <strong>lymphome cérébral</strong>.</ul>Les causes infectieuses sont :<ul><li>La <strong>méningite</strong>.</li><li>La <strong>méningo-encéphalite</strong>.</li><li>L'<strong>abcès cérébral</strong>.</li><li>L'<strong>empyème</strong>.</li></ul>"},{"i":"7e8bdef74fc3","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes inflammatoires ou carentielles de déficit neurologique récent d'origine encéphalique ?","a":"Les causes inflammatoires encéphaliques incluent :<ul><li>La <strong>poussée de SEP</strong> (Sclérose en Plaques).</li><li>La <strong>maladie de Behçet</strong>.</li><li>La <strong>sarcoïdose</strong>.</ul>La principale cause carentielle est l'<strong>encéphalopathie de Gayet-Wernicke</strong>."},{"i":"c86b32ad8de5","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes vasculaires, inflammatoires ou carentielles de déficit neurologique récent d'origine médullaire ?","a":"Les causes médullaires sont :<ul><li><strong>Vasculaire</strong> : l'<strong>infarctus médullaire</strong>, notamment suite à une <strong>dissection aortique</strong>.</li><li><strong>Inflammatoire</strong> : la <strong>myélite inflammatoire et infectieuse</strong>.</li><li><strong>Carentielle</strong> : la <strong>myélopathie carentielle</strong>.</li></ul>"},{"i":"35126145f787","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les étiologies des plexopathies, causes de déficits neurologiques périphériques ?","a":"<p>Les étiologies des plexopathies sont :</p><ul><li>Les causes <strong>traumatiques</strong>.</li><li>Les causes <strong>néoplasiques</strong>.</li><li>Le <strong>syndrome de Parsonage-Turner</strong>.</li></ul>"},{"i":"4c9ce50fde61","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les principales causes de neuropathies multifocales, un type de déficit neurologique périphérique récent ?","a":"<p>Les principales causes de neuropathies multifocales sont :</p><ul><li>Les causes <strong>vasculaires</strong> (comme les <strong>vascularites</strong>).</li><li>Le <strong>diabète</strong>.</li></ul>"},{"i":"a1fe987890b7","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les principales étiologies des neuropathies unifocales, causes de déficits neurologiques périphériques récents ?","a":"<p>Les principales étiologies des neuropathies unifocales sont :</p><ul><li>La <strong>compression traumatique</strong>.</li><li>La <strong>compression posturale</strong>.</li><li>L'<strong>ischémie</strong>.</li></ul>"},{"i":"cb32abc09e38","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelle est la principale cause d'une sciatique paralysante, représentant un déficit neurologique périphérique récent ?","a":"<p>La principale cause d'une sciatique paralysante est une <strong>atteinte uniradiculaire compressive</strong>, qui peut nécessiter une <strong>urgence chirurgicale</strong> si le déficit est sévère.</p>"},{"i":"ce5bc966ba5d","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les étiologies des polyradiculonévrites aiguës, causes de déficits neurologiques périphériques ?","a":"<p>Les étiologies des polyradiculonévrites aiguës incluent :</p><ul><li>Le <strong>syndrome de Guillain-Barré</strong> (polyradiculonévrite aiguë inflammatoire).</li><li>Les <strong>méningoradiculites infectieuses</strong>.</li><li>Les <strong>méningoradiculites néoplasiques</strong>.</li></ul>"},{"i":"e86f0bce9cc3","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les causes possibles du syndrome de la queue de cheval, un déficit neurologique périphérique récent ?","a":"<p>Les principales causes du syndrome de la queue de cheval sont :</p><ul><li>La <strong>hernie discale lombaire</strong>.</li><li>Les <strong>métastases</strong>.</li><li>L'<strong>épidurite</strong>.</li></ul>"},{"i":"3340656f7651","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Quels sont les trois principaux critères cliniques qui orientent vers une atteinte de la jonction neuromusculaire (JNM) ou du muscle lors d'un déficit neurologique récent ?","a":"<ul><li>Atteinte motrice pure, sans trouble sensitif ni vésicosphinctérien.</li><li>Déficit souvent proximal ; fatigabilité et fluctuation orientent vers la jonction.</li><li>ROT généralement conservés ; interpréter l’ensemble de l’examen.</li></ul>"},{"i":"3ecfe6189bbd","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Comment le test de la réponse idiomusculaire peut-il orienter vers une atteinte des muscles, et quel est le signe recherché ?","a":"<p>La percussion directe du muscle recherche sa contraction locale. Une réponse diminuée ou abolie est un argument myogène ; ce signe ne doit pas être attribué à la myasthénie.</p>"},{"i":"595d35de2c1e","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Quelles sont les causes à évoquer devant une atteinte de la jonction neuromusculaire ou du muscle, selon le contenu donné ?","a":"<p>Les principales causes à évoquer sont :</p><ul><li>Atteinte de la Jonction Neuromusculaire (JNM) : <strong>Myasthénie</strong> ou autres syndromes myasthéniques.</li><li>Atteinte musculaire de type <strong>Myosite</strong> : inflammatoire ou infectieuse.</li><li>Atteinte musculaire de type <strong>Myopathie</strong> : toxique ou métabolique (notamment les <strong>dyskaliémies</strong>).</li><li><strong>Rhabdomyolyse</strong> : nécrose musculaire aiguë, caractérisée par des <strong>CPK élevées</strong>.</li></ul>"},{"i":"c5f7b004f0e7","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Quel examen paraclinique est indiqué en cas de suspicion clinique d'atteinte de la jonction neuromusculaire ou du muscle ?","a":"<p>En cas de suspicion clinique d'atteinte de la jonction neuromusculaire ou du muscle, l'examen paraclinique indiqué est l'<strong>électromyogramme (EMG)</strong>.</p>"}],"courseEdition":{"date":"2026-10-12","source":"notion","objectivesReviewed":12,"notionUrl":"https://app.notion.com/p/2ad37f85d941813fbc06fdfdb9acc5ee?pvs=204","status":"reviewed"}};
